(2370197, 324965, 57169, '<td valign="top">Amazing - great work. Definately in the top 20.</td>', 'Amazing - great work. Definately in the top 20.', '2006-05-01 21:59:08.000000', NULL, 1),
(2370219, 326117, 57169, '<td valign="top">Love it. Nice detail.</td>', 'Love it. Nice detail.', '2006-05-01 22:03:52.000000', NULL, 1),
(2370225, 324447, 57169, '<td valign="top">Excellent work .One of my fav.</td>', 'Excellent work .One of my fav.', '2006-05-01 22:05:24.000000', NULL, 1),
(2370261, 324368, 57169, '<td valign="top">Stunning</td>', 'Stunning', '2006-05-01 22:16:48.000000', NULL, 1),
